        "content": ":root {
  --primary: #1a47ba;
  --primary-dark: #0d2f8b;
  --accent: #3c9aff;
  --bg-body: #f5f7fb;
  --bg-white: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-light: #e2e8f0;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
  --shadow-md: 0 4px 20px rgba(0,0,0,.10);
  --radius: 12px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg-body);
  color: var(--text-main);
  line-height: 1.65;
}
a { color: var(--primary); text-decoration:none; }
a:hover { text-decoration: underline; }
h1,h2,h3,h4,h5 {
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
}
p,li { color: var(--text-muted); }

/* ── LAYOUT WIKI ─────────────────────────────────── */
.wiki-wrapper {
  display: flex;
  min-height: 100vh;
}

.sidebar-wiki {
  width: 280px;          /* sidebar fijo a la izquierda */
  background: var(--bg-white);
  border-right: 1px solid var(--border-light);
  padding: 36px 24px 60px;
  position: sticky;
  top: 0;
}
.sidebar-wiki .logo-text {
  font-size: 1.15rem;   /* logo texto */
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 4px;
}
.sidebar-wiki .tagline {
  font-size: .72rem;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--text-muted);
  margin-bottom: 30px;
}
.sidebar-nav ul { list-style:none; }
.sidebar-nav li + li { padding-top: 8px; }
.sidebar-nav a {
  display: block;
  padding: 6px 12px;
  border-radius: 8px;
  font-size: .9rem;
  color: var(--text-muted);
  transition: background .2s, color .2s;
}
.sidebar-nav a:hover,
.sidebar-nav a.active {
  background: #eaf0ff;
  color: var(--primary);
}

.wiki-main-content {
  flex: 1;               /* contenido principal ocupa el resto */
  padding: 48px 56px;
  max-width: 920px;
}
.wiki-hero {
  margin-bottom: 48px;
}
.wiki-hero h1 { font-size: 2.3rem; color: var(--text-main); }
.wiki-hero .lead {
  margin-top: 6px;
  max-width: 70ch;
  font-size: 1.05rem;
}

/* ── SECCIONES / CARDS DE SERVICIOS ─────────────── */
.service-section { padding-bottom: 32px; }
.section-heading {
  display:flex; align-items:center; gap:14px;
  margin-bottom: 18px;
}
.section-icon {
  width: 40px; height: 40px;
  border-radius: 10px;
  background: #eaf0ff;
  color: var(--primary);
  display:flex; align-items:center; justify-content:center;
  font-size: 1.3rem;
}
.section-heading h2 { font-size: 1.45rem; }

/* cards internas */
.card-row {
  display: grid;
  gap: 18px;
  margin-bottom: 16px;
}
.card-row.cols-3 { grid-template-columns: repeat(3, minmax(0,1fr)); }
.card-row.cols-2 { grid-template-columns: repeat(2, minmax(0,1fr)); }

.service-card {
  background: var(--bg-white);
  border-radius: var(--radius);
  padding: 24px 22px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow .25s;
}
.service-card:hover { box-shadow: var(--shadow-md); }

.sc-header {
  display:flex; align-items:center; gap:10px;
  margin-bottom: 8px;
}
.sc-badge {
  width:34px; height:34px;
  border-radius:9px;
  background:#eaf0ff;
  color:var(--primary);
  display:flex;align-items:center;justify-content:center;font-size:.95rem;
}
.sc-header h4 { font-size:1.08rem; }

.service-card p {
  margin-bottom:6px;
  font-size:.92rem;
}
ul.feature-list { padding-left:1em; list-style:none; }
ul.feature-list li + li { margin-top:4px; }
ul.feature-list li::before { content:'•'; color:var(--primary); margin-right:8px; }

/* ── RESPONSIVE ─────────────────────────────────── */
@media (max-width:900px){
  .wiki-wrapper{ flex-direction:column; }
  .sidebar-wiki{
    width:auto;
    border-bottom:1px solid var(--border-light);
    padding:24px;
    position:relative;
  }
  .wiki-main-content{ padding:36px 20px; max-width:none; }
  .card-row.cols-3,.card-row.cols-2 { grid-template-columns:1fr; }
}
